package risksvc

import (
	"context"
	"database/sql"
	"fmt"
	"log/slog"
	"math"
	"strconv"
	"strings"
	"sync"
	"sync/atomic"
	"time"

	"github.com/easyspace-ai/polybet/internal/bookcache"
	"github.com/easyspace-ai/polybet/internal/config"
	"github.com/easyspace-ai/polybet/internal/polyexec"
	"github.com/easyspace-ai/polybet/internal/polywarm"
	"github.com/easyspace-ai/polybet/internal/polywiring"
	"github.com/easyspace-ai/polybet/internal/service/polysession"
	"github.com/easyspace-ai/polybet/internal/store"
	"github.com/easyspace-ai/polybet/internal/tg"
	"github.com/google/uuid"
)

type Service struct {
	cfg     *config.Config
	st      *store.Store
	cache   *bookcache.Cache
	log     *slog.Logger
	closeMu sync.Mutex
	closeLocks   sync.Map // map[string]*sync.Mutex per-position locks for ensureCloseTask

	userWSConnected   atomic.Bool
	userWSConnecting  atomic.Bool
	userWSLastMsgMs   atomic.Int64
	restTradesLastMs  atomic.Int64
	userWSLastIssueMu sync.Mutex
	userWSLastIssue   string

	// Gamma /markets cache for risk UI (token id → last fetch).
	gammaMetaMu sync.Mutex
	gammaMeta   map[string]gammaMetaCache
}

func New(cfg *config.Config, st *store.Store, cache *bookcache.Cache, log *slog.Logger) *Service {
	if log == nil {
		log = slog.Default()
	}
	return &Service{cfg: cfg, st: st, cache: cache, log: log}
}

// SetUserWSState updates dashboard-facing User WS meta (best-effort).
func (s *Service) SetUserWSState(connecting, connected bool, lastIssue string) {
	s.userWSConnecting.Store(connecting)
	s.userWSConnected.Store(connected)
	s.userWSLastIssueMu.Lock()
	s.userWSLastIssue = lastIssue
	s.userWSLastIssueMu.Unlock()
}

// TouchUserWSMessage marks receipt of a user-channel message (for dashboard meta).
func (s *Service) TouchUserWSMessage() {
	s.userWSLastMsgMs.Store(time.Now().UnixMilli())
}

func (s *Service) touchRESTTradesSync() {
	s.restTradesLastMs.Store(time.Now().UnixMilli())
}

func (s *Service) fillMeta(meta Meta) Meta {
	meta.UserWsConnected = s.userWSConnected.Load()
	meta.UserWsConnecting = s.userWSConnecting.Load()
	if ms := s.userWSLastMsgMs.Load(); ms > 0 {
		t := time.UnixMilli(ms).UTC().Format(time.RFC3339Nano)
		meta.UserWsLastMessageAt = &t
	}
	if ms := s.restTradesLastMs.Load(); ms > 0 {
		t := time.UnixMilli(ms).UTC().Format(time.RFC3339Nano)
		meta.RestTradesSyncLastAt = &t
	}
	s.userWSLastIssueMu.Lock()
	issue := s.userWSLastIssue
	s.userWSLastIssueMu.Unlock()
	if issue != "" {
		meta.UserWsLastIssue = &issue
	}
	return meta
}

func (s *Service) minShares(ctx context.Context) float64 {
	return s.st.GetBotConfigFloat(ctx, "minOpenRiskShares", 1)
}

func closeRetryMs(attempts int) int {
	n := max(1, attempts)
	if n <= 6 {
		v := 400 * int(math.Pow(2, float64(n-1)))
		if v > 10000 {
			return 10000
		}
		return v
	}
	v := 2000 * int(math.Pow(2, float64(minInt(n-6, 5))))
	if v > 60000 {
		return 60000
	}
	return v
}

func defaultBackoffMs(attempts int) int {
	v := 2000 * int(math.Pow(2, float64(minInt(attempts, 5))))
	if v > 60000 {
		return 60000
	}
	return v
}

func minInt(a, b int) int {
	if a < b {
		return a
	}
	return b
}

func (s *Service) bestBidCents(ctx context.Context, tokenID string) (float64, bool) {
	bb, _, ok := s.cache.TopOfBook(tokenID)
	if ok && bb > 0 {
		return bb * 100, true
	}
	cents, err := polywarm.BestBidCents(ctx, s.cfg.PolymarketAPIURL, s.cfg.HTTPPlatformProxy, tokenID)
	if err != nil {
		return 0, false
	}
	return cents, true
}

func (s *Service) UpdateHighWaterAndMaybeQueueStop(ctx context.Context, p store.RiskPosition, bidCents float64) (hw float64, trail float64, cur *float64, err error) {
	hw = p.HighWaterCents
	if bidCents > hw {
		hw = bidCents
		if err := s.st.UpdateRiskPositionHighWater(ctx, p.ID, hw); err != nil {
			return 0, 0, nil, err
		}
	}
	trail = hw * (1 - p.StopLossPct/100)
	curVal := bidCents
	cur = &curVal
	if p.Status == "open" && p.SizeShares >= s.minShares(ctx) && bidCents <= trail {
		if err := s.ensureCloseTask(ctx, p.ID, "stop_loss"); err != nil {
			return hw, trail, cur, err
		}
	}
	return hw, trail, cur, nil
}

// EnqueueClosePosition queues a manual close (same as Node enqueueClosePosition).
func (s *Service) EnqueueClosePosition(ctx context.Context, positionID string) error {
	s.log.Info("risk_close_enqueue", "position_id", positionID)
	return s.ensureCloseTask(ctx, positionID, "manual")
}

// queueReason: "manual" | "stop_loss" | "" (silent, e.g. batch from close_all).
func (s *Service) ensureCloseTask(ctx context.Context, positionID, queueReason string) error {
	lockI, _ := s.closeLocks.LoadOrStore(positionID, &sync.Mutex{})
	lock := lockI.(*sync.Mutex)
	lock.Lock()
	defer lock.Unlock()

	has, err := s.st.FindPendingCloseTask(ctx, positionID)
	if err != nil {
		s.log.Warn("risk_close_task_lookup_failed", "position_id", positionID, "err", err.Error())
		return err
	}
	if has {
		s.log.Info("risk_close_task_already_pending", "position_id", positionID)
		return nil
	}
	pos, _ := s.st.GetRiskPosition(ctx, positionID)
	t := &store.RiskTask{
		ID:         uuid.NewString(),
		Type:       "close_position",
		PositionID: sql.NullString{String: positionID, Valid: true},
		Status:     "pending",
		Attempts:   0,
		NextRunAt:  time.Now().UTC(),
	}
	if err := s.st.InsertRiskTask(ctx, t); err != nil {
		s.log.Error("risk_close_task_insert_failed", "position_id", positionID, "err", err.Error())
		return err
	}
	s.log.Info("risk_close_task_inserted", "position_id", positionID, "task_id", t.ID)
	if queueReason != "" {
		tg.Notify(ctx, s.cfg, s.st, s.log, formatCloseQueuedTelegram(queueReason, pos, positionID))
	}
	return nil
}

func formatCloseQueuedTelegram(reason string, pos *store.RiskPosition, positionID string) string {
	title := positionID
	if len(title) > 12 {
		title = title[:8] + "…"
	}
	shares := 0.0
	if pos != nil {
		if strings.TrimSpace(pos.Title) != "" {
			title = pos.Title
		}
		shares = pos.SizeShares
	}
	switch reason {
	case "manual":
		return fmt.Sprintf("Polybet 手动平仓已排队\n%s\n份额 %.2f", title, shares)
	case "stop_loss":
		return fmt.Sprintf("Polybet 移动止损触发，已排队平仓\n%s\n份额 %.2f", title, shares)
	default:
		return ""
	}
}

func (s *Service) RecordPolymarketBuyFill(ctx context.Context, outcomeID, tokenID, title, sideLabel string, fillOdds, costUsd float64) error {
	entry := fillOdds * 100
	if costUsd <= 0 || fillOdds <= 0 {
		return nil
	}
	newShares := costUsd / fillOdds
	if newShares <= 0 {
		return nil
	}
	_ = s.st.NormalizeDustRisk(ctx, 1e-9)
	stop := resolveStopLossPct(ctx, s.st, entry)
	return s.st.MergeOpenRiskBuy(ctx, tokenID, outcomeID, title, sideLabel, entry, newShares, costUsd, stop, "bot")
}

func (s *Service) ProcessRiskTasksOnce(ctx context.Context) error {
	tasks, err := s.st.ListDueRiskTasks(ctx, 20)
	if err != nil {
		return err
	}
	if len(tasks) == 0 {
		return nil
	}

	cl, err := polysession.ResolveAuthedCLOB(ctx, s.cfg, s.st)
	if err != nil {
		s.log.Warn("risk_task_batch_skip_no_clob", "task_count", len(tasks), "err", err.Error())
		return err
	}

	sellExtra := s.st.GetBotConfigInt(ctx, "polymarketFokSellExtraTicks", 5)
	concurrency := s.st.GetBotConfigInt(ctx, "closeTaskConcurrency", 10)
	if concurrency <= 0 {
		concurrency = 10
	}

	s.log.Info("risk_task_batch_start", "count", len(tasks), "concurrency", concurrency)

	// 按类型分组：close_all 串行执行（它内部会创建任务），close_position 并发执行
	var closeAllTasks []store.RiskTask
	var closePosTasks []store.RiskTask
	for _, t := range tasks {
		if t.Type == "close_all" {
			closeAllTasks = append(closeAllTasks, t)
		} else {
			closePosTasks = append(closePosTasks, t)
		}
	}

	var wg sync.WaitGroup
	sem := make(chan struct{}, concurrency)
	mu := sync.Mutex{}
	completed, failed := 0, 0

	// 并发执行 close_position 任务
	runClosePosTask := func(t store.RiskTask) {
		defer wg.Done()
		sem <- struct{}{}
		defer func() { <-sem }()

		_ = s.st.SetRiskTaskRunning(ctx, t.ID)
		s.log.Info("risk_task_run", "task_id", t.ID, "type", t.Type, "position_id", t.PositionID.String, "attempts", t.Attempts)

		runErr := s.runClosePosition(ctx, cl, t.ID, t.PositionID.String, sellExtra)
		if runErr != nil {
			att := t.Attempts + 1
			delay := closeRetryMs(att)
			msg := runErr.Error()
			if len(msg) > 2000 {
				msg = msg[:2000]
			}
			s.log.Warn("risk_task_failed", "task_id", t.ID, "type", t.Type, "next_attempt", att, "retry_delay_ms", delay, "err", msg)
			_ = s.st.SetRiskTaskFailed(ctx, t.ID, att, msg, time.Now().UTC().Add(time.Duration(delay)*time.Millisecond))
			mu.Lock()
			failed++
			mu.Unlock()
		} else {
			s.log.Info("risk_task_ok", "task_id", t.ID, "type", t.Type)
			mu.Lock()
			completed++
			mu.Unlock()
		}
	}

	for _, t := range closePosTasks {
		wg.Add(1)
		go runClosePosTask(t)
	}

	// 串行执行 close_all 任务
	for _, t := range closeAllTasks {
		wg.Add(1)
		go func(t store.RiskTask) {
			defer wg.Done()
			sem <- struct{}{}
			defer func() { <-sem }()

			_ = s.st.SetRiskTaskRunning(ctx, t.ID)
			s.log.Info("risk_task_run", "task_id", t.ID, "type", t.Type, "attempts", t.Attempts)

			runErr := s.runCloseAll(ctx, t.ID)
			if runErr != nil {
				att := t.Attempts + 1
				delay := defaultBackoffMs(att)
				msg := runErr.Error()
				if len(msg) > 2000 {
					msg = msg[:2000]
				}
				s.log.Warn("risk_task_failed", "task_id", t.ID, "type", t.Type, "next_attempt", att, "retry_delay_ms", delay, "err", msg)
				_ = s.st.SetRiskTaskFailed(ctx, t.ID, att, msg, time.Now().UTC().Add(time.Duration(delay)*time.Millisecond))
				mu.Lock()
				failed++
				mu.Unlock()
			} else {
				s.log.Info("risk_task_ok", "task_id", t.ID, "type", t.Type)
				mu.Lock()
				completed++
				mu.Unlock()
			}
		}(t)
	}

	wg.Wait()
	s.log.Info("risk_task_batch_done", "completed", completed, "failed", failed)
	return nil
}

func (s *Service) runClosePosition(ctx context.Context, cl *polywiring.AuthedCLOB, taskID, positionID string, sellExtra int) error {
	pos, err := s.st.GetRiskPosition(ctx, positionID)
	if err != nil || pos == nil || pos.Status == "closed" {
		s.log.Info("risk_close_skip_done", "task_id", taskID, "position_id", positionID, "reason", "missing_or_closed")
		return s.st.SetRiskTaskSucceeded(ctx, taskID)
	}
	if err := s.st.SetRiskPositionStatus(ctx, positionID, "closing"); err != nil {
		s.log.Warn("risk_close_status_closing_failed", "position_id", positionID, "err", err.Error())
		return err
	}
	s.log.Info("risk_close_fok_sell_send", "task_id", taskID, "position_id", positionID, "token_id", pos.TokenID, "size_shares", pos.SizeShares, "extra_ticks", sellExtra)
	_, err = polyexec.ExecuteFOKSell(ctx, cl.Client, cl.Signer, pos.TokenID, pos.SizeShares, sellExtra)
	if err != nil {
		_ = s.st.SetRiskPositionStatus(ctx, positionID, "open")
		s.log.Warn("risk_close_fok_sell_failed", "task_id", taskID, "position_id", positionID, "token_id", pos.TokenID, "err", err.Error())
		return err
	}
	if err := s.st.CloseRiskPosition(ctx, positionID); err != nil {
		s.log.Error("risk_close_db_close_failed", "position_id", positionID, "err", err.Error())
		return err
	}
	_ = s.st.CancelOtherCloseTasks(ctx, positionID, taskID)
	s.log.Info("risk_close_filled", "task_id", taskID, "position_id", positionID, "token_id", pos.TokenID)
	tg.Notify(ctx, s.cfg, s.st, s.log, fmt.Sprintf(
		"Polybet 平仓成交\n%s\n份额 %.2f · token %s",
		strings.TrimSpace(pos.Title),
		pos.SizeShares,
		pos.TokenID,
	))
	tg.MaybeNotifyCollateralChanged(s.cfg, s.log, s.st)
	return s.st.SetRiskTaskSucceeded(ctx, taskID)
}

func (s *Service) runCloseAll(ctx context.Context, taskID string) error {
	min := s.minShares(ctx)
	rows, err := s.st.ListOpenRiskPositionsMinShares(ctx, min)
	if err != nil {
		return err
	}
	s.log.Info("risk_close_all_run", "task_id", taskID, "open_positions", len(rows), "min_shares", min)
	if len(rows) == 0 {
		return s.st.SetRiskTaskSucceeded(ctx, taskID)
	}

	// 并发创建平仓任务
	concurrency := s.st.GetBotConfigInt(ctx, "closeAllConcurrency", 20)
	if concurrency <= 0 {
		concurrency = 20
	}
	sem := make(chan struct{}, concurrency)

	var wg sync.WaitGroup
	var mu sync.Mutex
	var failed int

	for _, p := range rows {
		wg.Add(1)
		go func(positionID string) {
			defer wg.Done()
			sem <- struct{}{}        // 获取信号量
			defer func() { <-sem }() // 释放

			if err := s.ensureCloseTask(ctx, positionID, ""); err != nil {
				mu.Lock()
				failed++
				mu.Unlock()
				s.log.Warn("risk_close_all_task_failed", "position_id", positionID, "err", err.Error())
			}
		}(p.ID)
	}
	wg.Wait()

	if err := s.st.SetRiskTaskSucceeded(ctx, taskID); err != nil {
		return err
	}
	s.log.Info("risk_close_all_done", "task_id", taskID, "enqueued_closes", len(rows)-failed, "failed", failed)
	tg.Notify(ctx, s.cfg, s.st, s.log, fmt.Sprintf("Polybet 一键平仓\n已为 %d 个持仓创建平仓任务", len(rows)-failed))
	return nil
}

func (s *Service) RiskEvaluateTokenAfterBookUpdate(ctx context.Context, tokenID string) error {
	min := s.minShares(ctx)
	rows, err := s.st.ListOpenRiskPositionsByToken(ctx, tokenID)
	if err != nil {
		return err
	}
	for _, p := range rows {
		if p.SizeShares < min {
			continue
		}
		bid, ok := s.bestBidCents(ctx, tokenID)
		if !ok {
			continue
		}
		_, _, _, err := s.UpdateHighWaterAndMaybeQueueStop(ctx, p, bid)
		if err != nil {
			s.log.Warn("risk evaluate", "err", err)
		}
	}
	return nil
}

func (s *Service) ApplyClobTradeIfNew(ctx context.Context, trade struct {
	ID, AssetID, Side, Size, Price, Status string
	Market, Outcome                        string
}) (bool, error) {
	st := strings.ToUpper(strings.TrimSpace(trade.Status))
	if st != "MATCHED" && st != "MINED" && st != "CONFIRMED" {
		return false, nil
	}
	_ = s.st.NormalizeDustRisk(ctx, 1e-9)
	ok, err := s.st.InsertRiskAppliedTrade(ctx, trade.ID)
	if err != nil || !ok {
		return false, err
	}
	size, _ := strconv.ParseFloat(strings.TrimSpace(trade.Size), 64)
	price, _ := strconv.ParseFloat(strings.TrimSpace(trade.Price), 64)
	if trade.AssetID == "" || size <= 0 || price <= 0 {
		return true, nil
	}
	side := strings.ToUpper(trade.Side)
	min := s.minShares(ctx)
	if side == "BUY" {
		entry := price * 100
		cost := size * price
		stop := resolveStopLossPct(ctx, s.st, entry)
		oid, has, _ := s.st.FindOutcomeIDByToken(ctx, trade.AssetID)
		outcomeID := ""
		if has {
			outcomeID = oid
		}
		title := "Polymarket"
		if trade.Market != "" {
			m := strings.TrimSpace(trade.Market)
			// User-channel payloads sometimes carry the full market question; keep it readable.
			if len(m) > 48 && !strings.HasPrefix(strings.ToLower(m), "0x") {
				title = m
			} else {
				title = "CLOB " + m[:minInt(len(m), 12)]
			}
		}
		sideLabel := trade.Outcome
		if sideLabel == "" {
			sideLabel = "YES"
		}
		if err := s.st.MergeOpenRiskBuy(ctx, trade.AssetID, outcomeID, title, sideLabel, entry, size, cost, stop, "polymarket_clob"); err != nil {
			return true, err
		}
		tg.Notify(ctx, s.cfg, s.st, s.log, fmt.Sprintf(
			"Polybet 成交同步（买入）\n%s\n%.2f 股 @ %.1f¢ · 成本约 $%.2f · trade %s",
			title, size, entry, cost, trade.ID,
		))
		tg.MaybeNotifyCollateralChanged(s.cfg, s.log, s.st)
		return true, nil
	}
	if side == "SELL" {
		if err := s.st.ReduceOpenRiskSell(ctx, trade.AssetID, size, price, min); err != nil {
			return true, err
		}
		tg.Notify(ctx, s.cfg, s.st, s.log, fmt.Sprintf(
			"Polybet 成交同步（卖出）\nasset %s\n%.2f 股 @ %.4f · trade %s",
			trade.AssetID, size, price, trade.ID,
		))
		tg.MaybeNotifyCollateralChanged(s.cfg, s.log, s.st)
		return true, nil
	}
	return true, nil
}

package risksvc

import (
	"context"
	"encoding/json"
	"net/url"
	"strings"
	"time"

	"github.com/easyspace-ai/polysdk/pkg/clob/clobtypes"

	"github.com/easyspace-ai/polybet/internal/gammaclient"
	"github.com/easyspace-ai/polybet/internal/polyexec"
	"github.com/easyspace-ai/polybet/internal/service/polysession"
	"github.com/easyspace-ai/polybet/internal/store"
)

const reconcileMinInterval = 60 * time.Second

type Meta struct {
	UserWsConnected         bool    `json:"userWsConnected"`
	UserWsConnecting        bool    `json:"userWsConnecting"`
	UserWsLastMessageAt     *string `json:"userWsLastMessageAt"`
	RestTradesSyncLastAt    *string `json:"restTradesSyncLastAt"`
	UserWsLastIssue         *string `json:"userWsLastIssue"`
	OutboundProxyConfigured bool    `json:"outboundProxyConfigured"`
	MinOpenRiskShares       float64 `json:"minOpenRiskShares"`
}

func firstNonEmpty(vals ...string) string {
	for _, v := range vals {
		if strings.TrimSpace(v) != "" {
			return strings.TrimSpace(v)
		}
	}
	return ""
}

// polymarketLinks builds human-facing Polymarket URLs from local DB sync + live Gamma /markets.
func polymarketLinks(dm store.RiskDisplayMeta, gm gammaclient.TokenMarketDisplay, title string) (eventURL, searchURL string) {
	slug := strings.Trim(firstNonEmpty(dm.PolySlug, gm.EventSlug, gm.Slug), "/")
	if slug != "" {
		slug = strings.TrimPrefix(slug, "event/")
		return "https://polymarket.com/event/" + slug, ""
	}
	cond := strings.TrimSpace(gm.ConditionID)
	if strings.HasPrefix(strings.ToLower(cond), "0x") {
		return "https://polymarket.com/market/" + cond, ""
	}
	if id := strings.Trim(strings.TrimSpace(dm.PolyEventID), "/"); id != "" {
		return "https://polymarket.com/event/" + id, ""
	}
	t := strings.TrimSpace(title)
	if t != "" {
		return "", "https://polymarket.com/search?q=" + url.QueryEscape(t)
	}
	return "", "https://polymarket.com/"
}

func (s *Service) ListRiskPositionsEnriched(ctx context.Context, meta Meta) ([]map[string]any, Meta, error) {
	meta = s.fillMeta(meta)
	_ = s.st.NormalizeDustRisk(ctx, 1e-9)
	if err := s.maybeReconcileBalances(ctx); err != nil {
		s.log.Warn("reconcile", "err", err)
	}
	min := s.minShares(ctx)
	rows, err := s.st.ListOpenOrClosingRiskPositions(ctx)
	if err != nil {
		return nil, meta, err
	}
	tokens := make([]string, 0, len(rows))
	for _, p := range rows {
		if tid := strings.TrimSpace(p.TokenID); tid != "" {
			tokens = append(tokens, tid)
		}
	}
	disp, derr := s.st.RiskDisplayMetaForPositions(ctx, rows)
	if derr != nil {
		s.log.Warn("risk_display_meta", "err", derr.Error())
		disp = map[string]store.RiskDisplayMeta{}
	}
	gammaByTok := s.gammaMetaBatch(ctx, tokens)
	out := make([]map[string]any, 0, len(rows))
	for _, p := range rows {
		if p.SizeShares < min && p.Status == "open" {
			continue
		}
		bid, ok := s.bestBidCents(ctx, p.TokenID)
		var hw, trail float64
		var curPtr *float64
		var err error
		if ok {
			hw, trail, curPtr, err = s.UpdateHighWaterAndMaybeQueueStop(ctx, p, bid)
			if err != nil {
				s.log.Warn("hw", "err", err)
			}
		} else {
			hw = p.HighWaterCents
			trail = hw * (1 - p.StopLossPct/100)
		}
		var valUsd, pnl *float64
		if curPtr != nil {
			v := *curPtr / 100
			vv := p.SizeShares * v
			valUsd = &vv
			pv := vv - p.CostUSD
			pnl = &pv
		}
		maxPay := p.SizeShares * 1
		pot := maxPay - p.CostUSD
		dm := disp[p.TokenID]
		gm := gammaByTok[p.TokenID]
		displayTitle := strings.TrimSpace(p.Title)
		if dm.HomeTeam != "" && dm.AwayTeam != "" {
			displayTitle = dm.HomeTeam + " vs " + dm.AwayTeam
		} else if strings.TrimSpace(gm.Question) != "" {
			displayTitle = gm.Question
		}
		sport := firstNonEmpty(dm.Sport, gm.Category)
		if sport != "" {
			sport = strings.ToLower(sport)
		}
		eventURL, searchURL := polymarketLinks(dm, gm, displayTitle)
		image := strings.TrimSpace(gm.Image)
		icon := strings.TrimSpace(gm.Icon)
		if icon == "" {
			icon = image
		}
		if image == "" {
			image = icon
		}
		m := map[string]any{
			"id": p.ID, "title": p.Title, "sideLabel": p.SideLabel,
			"displayTitle": displayTitle, "sport": sport,
			"officialUrl": eventURL, "officialSearchUrl": searchURL,
			"imageUrl": image,
			"iconUrl":  icon,
			"tokenId": p.TokenID,
			"avgEntryCents": p.AvgEntryCents, "currentCents": curPtr,
			"sizeShares": p.SizeShares, "costUsd": p.CostUSD,
			"highWaterCents": hw, "stopLossPct": p.StopLossPct,
			"trailingStopCents": trail, "valueUsd": valUsd, "pnlUsd": pnl,
			"maxPayoffUsd": maxPay, "potentialProfitUsd": pot,
			"status": p.Status, "source": p.Source,
		}
		out = append(out, m)
	}
	meta.MinOpenRiskShares = min
	return out, meta, nil
}

var lastReconcile time.Time

func (s *Service) maybeReconcileBalances(ctx context.Context) error {
	if time.Since(lastReconcile) < reconcileMinInterval {
		return nil
	}
	lastReconcile = time.Now()
	return s.ReconcileOpenRiskPositionsWithClobBalances(ctx)
}

func (s *Service) ReconcileOpenRiskPositionsWithClobBalances(ctx context.Context) error {
	cl, err := polysession.ResolveAuthedCLOB(ctx, s.cfg, s.st)
	if err != nil {
		return err
	}
	min := s.minShares(ctx)
	rows, err := s.st.ListRiskPositionsOpenClosing(ctx)
	if err != nil {
		return err
	}
	for _, p := range rows {
		bal, err := cl.Client.BalanceAllowance(ctx, &clobtypes.BalanceAllowanceRequest{
			AssetType: clobtypes.AssetTypeConditional,
			TokenID:   p.TokenID,
		})
		if err != nil {
			continue
		}
		onChain := polyexec.ConditionalBalanceShares(bal.Balance)
		if onChain < min {
			_ = s.st.CloseRiskPosition(ctx, p.ID)
			continue
		}
		if onChain+1e-9 < p.SizeShares {
			ratio := onChain / p.SizeShares
			newCost := max(0, p.CostUSD*ratio)
			_ = s.st.UpdateRiskPositionSharesCost(ctx, p.ID, onChain, newCost)
		}
	}
	return nil
}

func (s *Service) SyncRiskFromRESTTrades(ctx context.Context) error {
	cl, err := polysession.ResolveAuthedCLOB(ctx, s.cfg, s.st)
	if err != nil {
		return err
	}
	trades, err := cl.Client.Trades(ctx, &clobtypes.TradesRequest{})
	if err != nil {
		return err
	}
	n := len(trades.Data)
	if n > 100 {
		n = 100
	}
	for i := n - 1; i >= 0; i-- {
		t := trades.Data[i]
		_, _ = s.ApplyClobTradeIfNew(ctx, struct {
			ID, AssetID, Side, Size, Price, Status string
			Market, Outcome                        string
		}{ID: t.ID, AssetID: t.AssetID, Side: t.Side, Size: t.Size, Price: t.Price, Status: t.Status, Market: t.Market, Outcome: ""})
	}
	s.touchRESTTradesSync()
	return s.ReconcileOpenRiskPositionsWithClobBalances(ctx)
}

// ParseUserWsTradePayload mirrors Node parseUserWsTradePayload (minimal).
func ParseUserWsTradePayload(raw []byte) (struct {
	ID, AssetID, Side, Size, Price, Status string
	Market, Outcome                        string
}, bool) {
	var o map[string]any
	if err := json.Unmarshal(raw, &o); err != nil {
		return struct {
			ID, AssetID, Side, Size, Price, Status string
			Market, Outcome                        string
		}{}, false
	}
	et := strings.ToLower(anyStr(o["event_type"]))
	ty := strings.ToUpper(anyStr(o["type"]))
	if et != "trade" && ty != "TRADE" {
		return struct {
			ID, AssetID, Side, Size, Price, Status string
			Market, Outcome                        string
		}{}, false
	}
	id := anyStr(o["id"])
	aid := anyStr(o["asset_id"])
	if id == "" || aid == "" {
		return struct {
			ID, AssetID, Side, Size, Price, Status string
			Market, Outcome                        string
		}{}, false
	}
	return struct {
		ID, AssetID, Side, Size, Price, Status string
		Market, Outcome                        string
	}{
		ID: id, AssetID: aid, Side: anyStr(o["side"]), Size: anyStr(o["size"]), Price: anyStr(o["price"]), Status: anyStr(o["status"]),
		Market: anyStr(o["market"]), Outcome: anyStr(o["outcome"]),
	}, true
}

func anyStr(v any) string {
	if v == nil {
		return ""
	}
	switch t := v.(type) {
	case string:
		return t
	default:
		return ""
	}
